mapper.update:
MERGE INTO CRM_CODE_DETAIL A USING DUAL ON ( A.CODE_GROUP = #{code_group, jdbcType=VARCHAR} AND A.P_CODE = #{p_code, jdbcType=VARCHAR} AND A.CODE = #{code, jdbcType=VARCHAR} ) WHEN MATCHED THEN UPDATE SET A.CODE_NAME = #{code_name, jdbcType=VARCHAR} , A.USE_YN = #{use_yn, jdbcType=VARCHAR} , A.UPD_ID = #{reg_id, jdbcType=VARCHAR} , A.UPD_DATE = SYSDATE, A.VAL1 = #{val1, jdbcType=VARCHAR} , /*추가된 필드*/ A.VAL2 = #{val2, jdbcType=VARCHAR} , /*추가된 필드*/ A.VAL3 = #{val3, jdbcType=VARCHAR} , /*추가된 필드*/ A.VAL4 = #{val4, jdbcType=VARCHAR} , /*추가된 필드*/ A.VAL5 = #{val5, jdbcType=VARCHAR} , /*추가된 필드*/ A.VAL6 = #{val6, jdbcType=VARCHAR} , /*추가된 필드*/ A.VAL7 = #{val7, jdbcType=VARCHAR} , /*추가된 필드*/ A.VAL8 = #{val8, jdbcType=VARCHAR} , /*추가된 필드*/ A.VAL9 = #{val9, jdbcType=VARCHAR} , /*추가된 필드*/ A.VAL10 = #{val10, jdbcType=VARCHAR} , /*추가된 필드*/ A.SORT_ORD = #{sort_ord, jdbcType=VARCHAR} /*추가된 필드*/
WHEN NOT MATCHED THEN INSERT( A.CODE_GROUP, A.P_CODE, A.CODE , A.CODE_NAME , A.USE_YN , A.REG_ID , A.REG_DATE, VAL1, VAL2, VAL3, VAL4, VAL5, VAL6, VAL7, VAL8, VAL9, VAL10, SORT_ORD )VALUES( #{code_group, jdbcType=VARCHAR}, #{p_code, jdbcType=VARCHAR}, #{code, jdbcType=VARCHAR}, #{code_name, jdbcType=VARCHAR}, #{use_yn, jdbcType=VARCHAR}, #{reg_id, jdbcType=VARCHAR}, SYSDATE, #{val1, jdbcType=VARCHAR}, /*추가된 필드*/ #{val2, jdbcType=VARCHAR}, /*추가된 필드*/ #{val3, jdbcType=VARCHAR}, /*추가된 필드*/ #{val4, jdbcType=VARCHAR}, /*추가된 필드*/ #{val5, jdbcType=VARCHAR}, /*추가된 필드*/ #{val6, jdbcType=VARCHAR}, /*추가된 필드*/ #{val7, jdbcType=VARCHAR}, /*추가된 필드*/ #{val8, jdbcType=VARCHAR}, /*추가된 필드*/ #{val9, jdbcType=VARCHAR}, /*추가된 필드*/ #{val10, jdbcType=VARCHAR}, /*추가된 필드*/ #{sort_ord, jdbcType=VARCHAR} /*추가된 필드*/
)

